//! 日本語: 手書き有限Boolean oracle。ラベルはproduction評価器から生成しない。
//! English: Hand-authored Boolean gold labels, never generated by the evaluated checker.
use super::{Novelty, OracleLabel};
use crate::formal_boolean as formal;
use lc631_core::context::{ContextRevision, SourceRevision};
use lc631_solvers::typed_query::{
    BoolExpr, BoolSymbolId, QueryEmitError, SmtEmitLimits, SmtStatusQuery,
};
use lc631_substrate::Digest32;

/// Public demonstration corpus, not a sealed research holdout or natural-language gold.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ReferenceCase {
    Identity,
    Weaken,
    Strengthen,
    Negation,
    DeMorgan,
    Inconsistent,
}

pub const REFERENCE_CASES: [ReferenceCase; 6] = [
    ReferenceCase::Identity,
    ReferenceCase::Weaken,
    ReferenceCase::Strengthen,
    ReferenceCase::Negation,
    ReferenceCase::DeMorgan,
    ReferenceCase::Inconsistent,
];

impl ReferenceCase {
    pub const fn oracle(self) -> OracleLabel {
        match self {
            Self::Identity | Self::DeMorgan => OracleLabel::Valid,
            Self::Weaken | Self::Strengthen | Self::Negation => OracleLabel::Invalid,
            Self::Inconsistent => OracleLabel::Unlabelled,
        }
    }
    pub const fn novelty(self) -> Novelty {
        match self {
            Self::DeMorgan => Novelty::Permitted,
            Self::Identity | Self::Weaken | Self::Strengthen | Self::Negation => Novelty::NotNovel,
            Self::Inconsistent => Novelty::Unassessed,
        }
    }
    /// Source/target truth rows in order (p,q)=00,10,01,11.
    /// These literal independent values document the hand oracle, not a second parser.
    pub const fn predicate_rows(self) -> Option<([bool; 4], [bool; 4])> {
        match self {
            Self::Identity => Some(([false, true, false, true], [false, true, false, true])),
            Self::Weaken => Some(([false, true, false, true], [true, true, true, true])),
            Self::Strengthen => Some(([true, true, true, true], [false, true, false, true])),
            Self::Negation => Some(([false, true, false, true], [true, false, true, false])),
            Self::DeMorgan => Some(([true, true, true, false], [true, true, true, false])),
            Self::Inconsistent => None,
        }
    }
}

pub struct ReferenceFixture {
    source: SmtStatusQuery,
    target: SmtStatusQuery,
    source_predicate: BoolExpr,
    target_predicate: BoolExpr,
    symbols: [(BoolSymbolId, BoolSymbolId); 2],
    binding: formal::Binding,
}
impl ReferenceFixture {
    pub fn request(&self, hash_budget: u64) -> Result<formal::Request<'_>, formal::Failure> {
        let mut request = formal::Request {
            source: &self.source,
            target: &self.target,
            source_predicate: &self.source_predicate,
            target_predicate: &self.target_predicate,
            symbols: &self.symbols,
            unconstrained: formal::UnconstrainedPolicy::ExplicitlyGiven,
            binding: self.binding,
        };
        request.binding.probe_map = formal::probe_map_digest(&request, hash_budget)?;
        Ok(request)
    }
}

fn variable(id: u32) -> BoolExpr {
    BoolExpr::Variable(BoolSymbolId::new(id))
}
fn negate(value: BoolExpr) -> BoolExpr {
    BoolExpr::Not(Box::new(value))
}

/// Build typed IR only. No string parser, evaluator, oracle inference or network is used.
pub fn fixture(case: ReferenceCase) -> Result<ReferenceFixture, QueryEmitError> {
    let source = SmtStatusQuery::checked(
        vec![BoolSymbolId::new(0), BoolSymbolId::new(1)],
        vec![],
        vec![BoolExpr::Constant(case != ReferenceCase::Inconsistent)],
        SmtEmitLimits::default(),
    )?;
    let target = SmtStatusQuery::checked(
        vec![BoolSymbolId::new(10), BoolSymbolId::new(11)],
        vec![],
        vec![BoolExpr::Constant(true)],
        SmtEmitLimits::default(),
    )?;
    let (source_predicate, target_predicate) = match case {
        ReferenceCase::Identity | ReferenceCase::Inconsistent => (variable(0), variable(10)),
        ReferenceCase::Weaken => (variable(0), BoolExpr::Constant(true)),
        ReferenceCase::Strengthen => (BoolExpr::Constant(true), variable(10)),
        ReferenceCase::Negation => (variable(0), negate(variable(10))),
        ReferenceCase::DeMorgan => (
            negate(BoolExpr::And(vec![variable(0), variable(1)])),
            BoolExpr::Or(vec![negate(variable(10)), negate(variable(11))]),
        ),
    };
    let source_revision = SourceRevision::of("tlcx39.declared.manual.source.v1");
    let target_revision = SourceRevision::of("tlcx39.declared.manual.target.v1");
    Ok(ReferenceFixture {
        source,
        target,
        source_predicate,
        target_predicate,
        symbols: [
            (BoolSymbolId::new(0), BoolSymbolId::new(10)),
            (BoolSymbolId::new(1), BoolSymbolId::new(11)),
        ],
        binding: formal::Binding {
            source: source_revision,
            target: target_revision,
            source_context: ContextRevision::original(source_revision),
            target_context: ContextRevision::original(target_revision),
            probe_set: Digest32::from_bytes([39; 32]),
            probe_map: Digest32::from_bytes([0; 32]),
        },
    })
}
